let _isTerminating = false;

export const isSessionTerminating = () => _isTerminating;

/**
 * Centralized session termination function.
 *
 * Performs complete cleanup of all client-side session state:
 * 1. Notifies the server to invalidate the session (must complete before redirect
 *    so the HttpOnly cookie delete-cookie response is processed by the browser)
 * 2. Disconnects the socket.io connection
 * 3. Terminates active Web Workers (TTS)
 * 4. Resets all Svelte stores to their initial values
 * 5. Clears ALL localStorage and sessionStorage
 * 6. Redirects to the auth page using location.replace() to prevent back-button re-entry
 */
export const terminateSession = async (options?: { redirect?: boolean }) => {
	if (_isTerminating) return;
	_isTerminating = true;

	const shouldRedirect = options?.redirect ?? true;

	// 1. Server-side session invalidation — MUST complete before redirect
	//    so the Set-Cookie: token=; Max-Age=0 response header is applied by the browser,
	//    which deletes the HttpOnly auth cookie that JS cannot access.
	try {
		await userSignOut();
	} catch (e) {
		console.warn('Server-side signout failed (session may already be expired):', e);
	}

	// 2. Import stores dynamically to avoid circular dependency issues
	const stores = await import('$lib/stores');

	// 3. Disconnect socket.io
	try {
		let socketInstance: { disconnect: () => void } | null = null;
		stores.socket.subscribe((s) => {
			socketInstance = s as { disconnect: () => void } | null;
		})();
		if (socketInstance) {
			socketInstance.disconnect();
		}
		stores.socket.set(null);
	} catch (e) {
		console.warn('Socket disconnect failed:', e);
	}

	// 4. Terminate active Web Workers
	try {
		let ttsWorkerInstance: { worker: { terminate: () => void } } | null = null;
		stores.TTSWorker.subscribe((w) => {
			ttsWorkerInstance = w as { worker: { terminate: () => void } } | null;
		})();
		if (ttsWorkerInstance?.worker) {
			ttsWorkerInstance.worker.terminate();
		}
		stores.TTSWorker.set(null);
	} catch (e) {
		console.warn('TTSWorker terminate failed:', e);
	}

	// 5. Reset all Svelte stores to initial values
	stores.user.set(undefined);
	stores.config.set(undefined);
	stores.models.set([]);
	stores.chats.set(null);
	stores.tags.set([]);
	stores.pinnedChats.set([]);
	stores.prompts.set(null);
	stores.knowledge.set(null);
	stores.tools.set(null);
	stores.functions.set(null);
	stores.banners.set([]);
	stores.settings.set({});
	stores.activeUserIds.set(null);
	stores.USAGE_POOL.set(null);
	stores.toolServers.set([]);
	stores.showSettings.set(false);
	stores.showArchivedChats.set(false);
	stores.showChangelog.set(false);
	stores.showControls.set(false);
	stores.showOverview.set(false);
	stores.showArtifacts.set(false);
	stores.showCallOverlay.set(false);
	stores.temporaryChatEnabled.set(false);

	// 6. Clear ALL client-side storage
	try {
		localStorage.clear();
	} catch {
		const keys = ['token', 'settings', 'theme', 'locale', 'dismissedUpdateToast'];
		keys.forEach((key) => {
			try {
				localStorage.removeItem(key);
			} catch {
				// ignore per-key removal failure
			}
		});
	}

	try {
		sessionStorage.clear();
	} catch {
		// ignore sessionStorage clear failure
	}

	// 7. Reset guard BEFORE redirect (redirect is a hard navigation — code below won't execute)
	_isTerminating = false;

	if (shouldRedirect) {
		window.location.replace('/auth');
	}
};

/**
 * Installs a global fetch interceptor that automatically terminates the session
 * when a 401 Unauthorized response is received from an API call, indicating the
 * session token is no longer valid.
 *
 * Important: it only reacts to 401 (invalid/expired session) and NOT 403, because
 * 403 means "authenticated but not allowed" (e.g. a locked-account sign-in, or an
 * action the user lacks permission for) — terminating the session on 403 would log
 * users out on legitimate authorization failures. It also ignores the
 * unauthenticated auth-flow endpoints and never fires while on the /auth page.
 * Must be called once during app initialization.
 */
export const installUnauthorizedInterceptor = () => {
	const originalFetch = window.fetch;

	window.fetch = async (...args) => {
		const response = await originalFetch.apply(window, args);

		if (response.status === 401 && !_isTerminating) {
			const url = typeof args[0] === 'string' ? args[0] : (args[0] as Request).url;

			const isApi = typeof url === 'string' && url.includes('/api/');
			// Sign-in / sign-up / LDAP / sign-out legitimately return 401/4xx without
			// implying an existing session became invalid — don't tear down on those.
			const isAuthFlow =
				typeof url === 'string' && /\/(auths|auth)\/(signin|signup|ldap|signout)/.test(url);
			const onAuthPage = typeof window !== 'undefined' && window.location?.pathname === '/auth';

			if (isApi && !isAuthFlow && !onAuthPage) {
				console.warn(`Received 401 from ${url} - terminating session`);
				terminateSession();
			}
		}

		return response;
	};
};

export const unlockUserAccount = async (token: string, userId: string) => {
	return apiClient.post(`/users/${userId}/unlock`, undefined, { token });
};

export const uploadLogo = async (token: string, file: File) => {
	const formData = new FormData();
	formData.append('file', file);
	return apiClient.post('/auths/admin/logo', formData, { token });
};

export const deleteLogo = async (token: string) => {
	return apiClient.del('/auths/admin/logo', undefined, { token });
};

export const getUserLockoutStatuses = async (token: string) => {
	return apiClient.get('/users/lockout-statuses', { token });
};
